/**
 * ملفات صورة المشاركة، محفوظة كـ base64 جوه الكود عشان تشتغل على Vercel من غير قراءة ملفات.
 * الخطوط: IBM Plex Sans Arabic (نفس خط الموقع) من @fontsource، بصيغة woff لأن المكتبة مبتقراش woff2.
 * متقصّتش، لأن تقصيص الخط بيكسر توصيل الحروف العربية في المكتبة.
 * اللوجو: نفس لوجو الموقع بمقاس ٣٦٠×٩٠ ولون كريمي.
 * الملف ده متولّد، فمتعدّلوش بإيدك.
 */
const decode = (s: string): ArrayBuffer => {
  const bin = atob(s);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out.buffer;
};

export const ogFonts = () => [
  { name: "Plex", data: decode(AR_400), weight: 400 as const, style: "normal" as const },
  { name: "Plex", data: decode(AR_600), weight: 600 as const, style: "normal" as const },
  { name: "PlexLatin", data: decode(LA_500), weight: 500 as const, style: "normal" as const },
];

export const OG_LOGO = "data:image/png;base64,";

const AR_400 = "";
const AR_600 = "";
const LA_500 = "";
